// Counter plays the role of a 'use client' island
function Counter({ start, label }) {
  const [n, setN] = useState(start);
  return (
    <button onClick={() => setN(n + 1)} style={{ padding: '6px 10px' }}>
      {label}: {n}
    </button>
  );
}
function App() {
