solution.code:
function App() {
  const answers = {
    'await db.query(...)': 'server (direct backend access)',
    'useState / useEffect': 'client (needs a client runtime)',
    'onClick handler': 'client (event handlers are client-only)',
    'read process.env secret': 'server (never expose secrets to the browser)',
    'window / localStorage': 'client (browser APIs only exist there)',
  };
  return (
    <ul style={{ fontFamily: 'system-ui', padding: 16 }}>
      {Object.entries(answers).map(([k, v]) => <li key={k} style={{ margin: '4px 0' }}><code>{k}</code>: {v}</li>)}
    </ul>
  );
}

