// Illustrative fix — split server data from client interactivity:
function App() {
  const src = [
    "// app/profile/Toggle.tsx",
    "'use client';",
    "export function Toggle({ name }: { name: string }) {",
    "  const [open, setOpen] = useState(false);",
    "  return <button onClick={() => setOpen(o => !o)}>{open ? name : 'Show'}</button>;",
    "}",
    "",
    "// app/profile/page.tsx (Server Component)",
    "export default async function Page() {",
    "  const user = await db.user.find();      // stays on the server",
    "  return <Toggle name={user.name} />;     // serializable prop crosses the boundary",
    "}",
  ];
  return <pre style={{ padding: 16, fontFamily: 'ui-monospace, monospace', fontSize: 12 }}>{src.join('\n')}</pre>;
}

// app/likes/LikeButton.tsx
'use client';
import { useState } from 'react';

export function LikeButton({ initial, label }: { initial: number; label: string }) {
  const [count, setCount] = useState(initial);
  return (
    <button onClick={() => setCount((c) => c + 1)}>
      {label}: {count}
    </button>
  );
}

// app/likes/page.tsx — async Server Component (no 'use client')
import { db } from '@/lib/db';
import { LikeButton } from './LikeButton';

export default async function Page() {
  const post = await db.post.findFirst(); // direct backend access, ships no JS
  return (
    <article>
      <h1>{post.title}</h1>
      {/* serializable props cross the boundary */}
      <LikeButton initial={post.likes} label="Likes" />
    </article>
  );
}
